def test_concurrent_commits_never_expose_half_batches(self) -> None:
    batch_count, batch_size = 12, 5
    stop = threading.Event()
    violations: list[str] = []
    read_errors: list[BaseException] = []
    write_errors: list[tuple[str, object]] = []
    seen_pages: list[int] = []

    def reader() -> None:
        try:
